#include <stdio.h>
#include <stdlib.h>

// Global variables
int edge_a[6];
int edge_b[6];
int edge_w[6];
int parent[6];

int find(int i) {
    if (parent[i] == i)
        return i;
    return find(parent[i]);
}

void union_set(int u, int v) {
    int x = find(u);
    int y = find(v);
    parent[x] = y;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <number_of_vertices>\n", argv[0]);
        return 1;
    }
    int num_vertices = atoi(argv[1]);
    int num_edges = 0;
    int weight = 0;
    for (int i = 0; i < num_vertices; i++) {
        parent[i] = i;
    }
    for (int i = 0; i < 6; i++) {
        if (edge_w[i] != 0) {
            int u = edge_a[i];
            int v = edge_b[i];
            int w = edge_w[i];
            if (find(u) != find(v)) {
                printf("%d-%d", u, v);
                putchar(',');
                union_set(u, v);
                weight += w;
                num_edges++;
            }
        }
    }
    printf("weight=%d edges=%d\n", weight, num_edges);
    return 0;
}
